/* ==== 内嵌字体：JetBrains Sans 变量体 + Mono + Noto Sans CJK 子集（1871 字符）==== */
@font-face{font-family:"JetBrains Sans";src:url(data:font/ttf;base64,) format("truetype-variations");font-weight:100 900;font-style:normal;font-display:swap}
@font-face{font-family:"JetBrains Mono";src:url(data:font/woff2;base64,) format("woff2");font-weight:400;font-style:normal;font-display:swap}
@font-face{font-family:"JetBrains Mono";src:url(data:font/woff2;base64,) format("woff2");font-weight:500;font-style:normal;font-display:swap}
@font-face{font-family:"JetBrains Mono";src:url(data:font/woff2;base64,) format("woff2");font-weight:700;font-style:normal;font-display:swap}
@font-face{font-family:"Noto Sans CJK SC";src:url(data:font/woff2;base64,) format("woff2");font-weight:100 549;font-style:normal;font-display:swap}
@font-face{font-family:"Noto Sans CJK SC";src:url(data:font/woff2;base64,) format("woff2");font-weight:550 900;font-style:normal;font-display:swap}

/* ==========================================================================
   mellum-theme.css —— 全站 Mellum 2 主题覆盖层
   作用：在不重写任何页面结构的前提下，把站点所有模板切到 JetBrains
        Mellum 2 深色课件风格。按各模板自己的 :root 变量名逐一覆盖，
        再补上少量"变量覆盖不到"的全局规则（白底、阴影、圆角、字体）。
   使用：在每页原有的 <style> 之后引入本文件（见 inject.py）。
   ========================================================================== */

/* --------------------------------------------------------------------------
   1. 通用 Mellum 基础 token（页面自有的变量名会各自覆盖一次）
   -------------------------------------------------------------------------- */
:root{
  --mellum-bg:        #000000;
  --mellum-panel:     #131316;
  --mellum-panel-alt: #18181B;
  --mellum-inset:     #0B0B0D;
  --mellum-line:      #3F3F46;
  --mellum-hairline:  #1F1F23;

  --mellum-ink:       #FFFFFF;
  --mellum-ink-body:  #DADADA;
  --mellum-ink-muted: #B8B8B8;
  --mellum-ink-dim:   #8C8C8C;
  --mellum-ink-faint: #70707A;

  --mellum-blue:      #087CFA;
  --mellum-cyan:      #07C3F2;
  --mellum-teal:      #10A99A;
  --mellum-green:     #20D689;
  --mellum-orange:    #E8641F;
  --mellum-accent:    #EC4899;

  --mellum-grad: linear-gradient(90deg,#087CFA 0%,#10A99A 62%,#20D689 100%);
  --mellum-sans: "JetBrains Sans","Noto Sans CJK SC","PingFang SC",
                 "Hiragino Sans GB","Microsoft YaHei",system-ui,sans-serif;
  --mellum-mono: "JetBrains Mono",ui-monospace,"SF Mono",SFMono-Regular,
                 Menlo,Consolas,monospace;
}

/* --------------------------------------------------------------------------
   2. ics 课件族（29 讲正文 + Data Lab / Bomb Lab / Attack Lab）
      —— 模板变量最全的一套，53 个
   -------------------------------------------------------------------------- */
:root{
  --bg:#000000; --card:#131316; --ink:#FFFFFF; --muted:#B8B8B8; --line:#3F3F46;
  --accent:#087CFA; --accent-ink:#FFFFFF; --accent-soft:rgba(8,124,250,.12);
  --sign:#EC4899; --exp:#07C3F2; --frac:#10A99A; --warn:#E8641F;

  --sign-bg:rgba(236,72,153,.10); --sign-fg:#F472B6; --sign-bd:rgba(236,72,153,.40);
  --exp-bg:rgba(7,195,242,.10);   --exp-fg:#38BDF8;  --exp-bd:rgba(7,195,242,.40);
  --frac-bg:rgba(16,169,154,.10); --frac-fg:#2DD4BF; --frac-bd:rgba(16,169,154,.40);
  --ok-bg:rgba(16,169,154,.10);   --ok-bd:rgba(16,169,154,.40);
  --bad-bg:rgba(232,100,31,.10);  --bad-bd:rgba(232,100,31,.40);
  --warn-bg:rgba(232,100,31,.10);
  --gray-bg:#1F1F23; --gray-fg:#B8B8B8;
  --paper-soft:#0B0B0D; --code-bg:#0B0B0D; --code-bd:#3F3F46;
  --tbl-head:#131316; --tbl-hover:#18181B; --sel-bg:#1F1F23;

  --font-sans:var(--mellum-sans); --font-mono:var(--mellum-mono);
  --font-display:var(--mellum-sans); --tracking-title:0;

  --radius:6px; --radius-sm:4px; --radius-pill:99px;
  --border-w:1px; --shadow:none; --shadow-card:none;
  --card-border:1px solid #3F3F46;

  --page-max:1180px; --nav-w:212px; --gap:32px; --sec-pad:26px 28px;
  --nav-sticky-top:64px; --anchor-offset:70px;
  --font-size:16px; --line-height:1.52;
}

/* --------------------------------------------------------------------------
   3. Data Lab 族（datalab / bomblab / bits / floating-point 的另一种模板）
   -------------------------------------------------------------------------- */
:root{
  --accent:#087CFA; --accent-soft:rgba(8,124,250,.12);
  --bg:#000000; --card:#131316; --ink:#FFFFFF; --line:#3F3F46;
  --muted:#B8B8B8; --mono:var(--mellum-mono); --sans:var(--mellum-sans);
  --sign:#EC4899; --exp:#07C3F2; --frac:#10A99A; --warn:#E8641F;
  --radius:6px; --shadow:none;
}

/* --------------------------------------------------------------------------
   4. 落地页 / 各目录索引（6 变量极简模板）
   -------------------------------------------------------------------------- */
:root{
  --accent:#087CFA; --bg:#000000; --card:#131316;
  --ink:#FFFFFF; --line:#3F3F46; --muted:#B8B8B8;
}

/* --------------------------------------------------------------------------
   5. 终端类（gitlearn / shelllearn）—— 本来就是深色，只做对齐
   -------------------------------------------------------------------------- */
:root{
  --bg:#000000; --panel:#131316; --panel-2:#18181B; --panel-3:#1F1F23;
  --border:#3F3F46; --text:#DADADA; --muted:#B8B8B8; --dim:#8C8C8C;
  --green:#10A99A; --red:#E8641F; --yellow:#E8641F; --blue:#087CFA;
  --purple:#B8B8B8; --teal:#10A99A;
  --sans:var(--mellum-sans); --mono:var(--mellum-mono);
}

/* --------------------------------------------------------------------------
   6. 美术单页（qinshihuang）—— 朱砂金换成 Mellum 的蓝青绿
   -------------------------------------------------------------------------- */
:root{
  --cinnabar:#087CFA; --gold:#20D689; --gold-2:#10A99A;
  --ink:#FFFFFF; --ink-2:#DADADA; --line:#3F3F46;
  --panel:#131316; --paper:#000000; --paper-dim:#0B0B0D;
  --txt:#DADADA; --txt-dim:#8C8C8C;
  --sans:var(--mellum-sans); --serif:var(--mellum-sans);
  --sky-a:#000000; --sky-b:#04101F; --sky-c:#061A33;
}

/* ==========================================================================
   7. 全局规则：变量覆盖不到的地方
   ========================================================================== */

html{background:#000 !important}
body{
  background:#000 !important;
  color:#DADADA !important;
  font-family:var(--mellum-sans) !important;
  -webkit-font-smoothing:antialiased;
  text-rendering:optimizeLegibility;
}

/* 标题纯白；正文保持 #DADADA（五级灰阶的层次靠亮度差，不靠字号） */
h1,h2,h3,h4,h5,h6{color:#FFFFFF !important}
h1,h2{font-weight:600 !important;letter-spacing:0 !important}

/* 正文段落明确用 body 灰，避免继承到纯白 */
p,li,dd,dt,figcaption{color:#DADADA}

/* 链接：品牌蓝，下划线用低透明度 */
a{color:#087CFA}
a:hover{color:#4FA6FF}

/* 零阴影、小圆角：Mellum 的抬升只靠 #131316 + 1px 描边 */
*,*::before,*::after{box-shadow:none !important}
[style*="box-shadow"]{box-shadow:none !important}

/* 选中态用粉色（数据/当前的唯一语义） */
::selection{background:rgba(236,72,153,.28);color:#FFF}

/* 焦点环用白色，不用粉色 */
:focus-visible{outline:2px solid #FFFFFF;outline-offset:2px}

/* 代码块统一到 inset 底 */
pre,code,kbd,samp{
  font-family:var(--mellum-mono) !important;
  background-color:#0B0B0D !important;
  border-color:#3F3F46 !important;
  color:#DADADA !important;
}

/* 表格：去掉斑马纹的浅底，行线用 #3F3F46 */
table{border-color:#3F3F46 !important}
th{color:#B8B8B8 !important;font-weight:400 !important}
td{border-color:#3F3F46 !important}

/* 分隔线 */
hr{border-color:#1F1F23 !important}

/* 输入类控件 */
input,textarea,select{
  background-color:#0B0B0D !important;
  color:#DADADA !important;
  border-color:#3F3F46 !important;
  font-family:var(--mellum-sans) !important;
}
input::placeholder,textarea::placeholder{color:#70707A !important}

/* 卡片的浅色底一律压到 #131316，描边到 #3F3F46 */
[class*="card"],[class*="panel"],[class*="box"]{
  border-color:#3F3F46;
}

/* 响应式与无障碍 */
@media (prefers-reduced-motion: reduce){
  *{transition:none !important;animation:none !important}
}
@media print{
  html,body{background:#000 !important}
  *{box-shadow:none !important}
}

/* ==========================================================================
   8. 兜底：把模板里"硬编码"的浅色值统一压到 Mellum 深色系
      有些模板（尤其 Data Lab 族、各风格变体）不是全靠变量取色，
      直接写了 #fff / #f8fafc / #fdecec 这类浅色。变量覆盖管不到，
      所以按属性再兜一层。
   ========================================================================== */

/* ---- 8.1 背景：凡是浅色一律换成分层深色 ---- */
[style*="background:#fff"],[style*="background: #fff"],
[style*="background:#ffffff"],[style*="background: #ffffff"],
[style*="background:white"],[style*="background: white"]{
  background-color:#131316 !important;
}
[style*="background:#f"],[style*="background: #f"]{
  background-color:#18181B !important;
}

/* 常见组件：卡片/盒子/公式/步骤/折叠块/选项/表格头 —— 统一深底 + 描边 */
.card,.box,.step,.reveal,.puzzle,.formula,.panel,.tile,.item,
.puzzle.correct,.puzzle.wrong,.box.ok,.box.bad,.box.warn,
.step.on,.reveal[open]{
  background-color:#131316 !important;
  border-color:#3F3F46 !important;
  color:#DADADA !important;
}
.card p,.box p,.step p,.reveal p,.puzzle p,.formula,.tile p,.item p{
  color:#DADADA !important;
}
.card strong,.box strong,.step strong,.reveal strong,.puzzle strong{
  color:#FFFFFF !important;
}
/* 卡片内的小标题 */
.card h1,.card h2,.card h3,.card h4,.card h5,
.box h1,.box h2,.box h3,.box h4,.box h5,
.step h1,.step h2,.step h3,.step h4,.step h5{
  color:#FFFFFF !important;
}

/* ---- 8.2 强调底色块：浅色底换成低透明度实色 ---- */
.bits .b.s,.chip.bad,.box.bad{
  background-color:rgba(236,72,153,.12) !important;
  color:#F472B6 !important;
  border-color:rgba(236,72,153,.40) !important;
}
.bits .grp.gs{background-color:rgba(236,72,153,.07) !important}
.bits .grp.ge{background-color:rgba(7,195,242,.07) !important}
.bits .grp.gf{background-color:rgba(16,169,154,.07) !important}
.box.ok,.puzzle.correct{
  background-color:rgba(16,169,154,.10) !important;
  border-color:rgba(16,169,154,.40) !important;
}
.box.warn,.chip.warn{
  background-color:rgba(232,100,31,.10) !important;
  border-color:rgba(232,100,31,.40) !important;
  color:#E8641F !important;
}
.puzzle.wrong{
  background-color:rgba(232,100,31,.10) !important;
  border-color:rgba(232,100,31,.40) !important;
}

/* ---- 8.3 表格 ---- */
table.tbl th{background-color:#131316 !important;color:#B8B8B8 !important}
table.tbl tr:hover td{background-color:#18181B !important}
table.tbl td{border-color:#3F3F46 !important;color:#DADADA}
table.tbl .num{color:#B8B8B8}

/* ---- 8.4 顶栏/导航/工具条的浅色底 ---- */
.topbar,nav.toc,.stylebar,.seg,.toolbar,.navbar,header.sticky{
  background-color:#0B0B0D !important;
  border-color:#3F3F46 !important;
}
.topbar *,.stylebar *,.seg *{color:#B8B8B8}
.stylebar a.cur,.seg button.on{
  background-color:#087CFA !important;
  color:#FFFFFF !important;
  border-color:#087CFA !important;
}

/* ---- 8.5 按钮：浅底 → 深底，主按钮用 Mellum 蓝 ---- */
button{
  background-color:#18181B !important;
  color:#DADADA !important;
  border-color:#3F3F46 !important;
}
button:hover{background-color:#1F1F23 !important;color:#FFFFFF !important}
button.p,button.primary,.btn-primary{
  background-color:#087CFA !important;
  color:#FFFFFF !important;
  border-color:#087CFA !important;
}

/* ---- 8.6 代码与行内代码 ---- */
code,kbd,samp{background-color:#0B0B0D !important;color:#DADADA !important;border-color:#3F3F46 !important}
pre{background-color:#0B0B0D !important;border-color:#3F3F46 !important}
pre code{background:none !important;border:0 !important}

/* ---- 8.7 表单单控件 ---- */
input,textarea,select{
  background-color:#0B0B0D !important;
  color:#DADADA !important;
  border-color:#3F3F46 !important;
}
input:focus,textarea:focus,select:focus{border-color:#8C8C8C !important}

/* ---- 8.8 目录/侧栏当前项 ---- */
nav.toc a.active,nav.toc a[aria-current="true"],.toc a.on{
  background-color:rgba(8,124,250,.14) !important;
  color:#FFFFFF !important;
  border-left-color:#FFFFFF !important;
}

/* ---- 8.9 进度条 / 条形图底色 ---- */
progress,.bar,.track,.progress{background-color:#1F1F23 !important;border-color:#3F3F46 !important}

/* ---- 8.10 亮色变体页（学术/玻璃/粗野）里写死的白卡 ---- */
[class*="variant"] .card,[class*="variant"] .panel{background-color:#131316 !important}
